-- Parent and student portal (ADR-0022): a login is STAFF, or a PARENT linked to a guardian, or
-- a STUDENT linked to their own record. Generated by Prisma; the check at the end added by hand.


-- CreateEnum
CREATE TYPE "UserKind" AS ENUM ('STAFF', 'PARENT', 'STUDENT');

-- AlterTable
ALTER TABLE "users" ADD COLUMN     "guardian_id" UUID,
ADD COLUMN     "kind" "UserKind" NOT NULL DEFAULT 'STAFF',
ADD COLUMN     "student_id" UUID;

-- CreateIndex
CREATE UNIQUE INDEX "users_guardian_id_key" ON "users"("guardian_id");

-- CreateIndex
CREATE UNIQUE INDEX "users_student_id_key" ON "users"("student_id");

-- AddForeignKey
ALTER TABLE "users" ADD CONSTRAINT "users_guardian_id_fkey" FOREIGN KEY ("guardian_id") REFERENCES "guardians"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "users" ADD CONSTRAINT "users_student_id_fkey" FOREIGN KEY ("student_id") REFERENCES "students"("id") ON DELETE CASCADE ON UPDATE CASCADE;


-- (by hand) The link must match the kind of login.
ALTER TABLE "users" ADD CONSTRAINT "users_kind_link_check" CHECK (
  ("kind" = 'STAFF' AND "guardian_id" IS NULL AND "student_id" IS NULL)
  OR ("kind" = 'PARENT' AND "guardian_id" IS NOT NULL AND "student_id" IS NULL)
  OR ("kind" = 'STUDENT' AND "student_id" IS NOT NULL AND "guardian_id" IS NULL)
);
